const h = params.height;
const floors = params.floors;
const floorH = h / floors;
const w = h * 0.22;
const d = h * 0.18;
const podiumH = Math.max(2.8, h * 0.065);
const tier1Top = Math.max(3, Math.floor(floors * 0.48));
const tier2Top = Math.max(tier1Top + 2, Math.floor(floors * 0.78));
const glass = { preset: 'glass', color: params.glassColor, roughness: 0.16, metalness: 0.12, opacity: 0.9 };
const frame = { preset: 'metal', color: '#26333b', roughness: 0.28, metalness: 0.72 };
const trim = { preset: 'metal', color: '#aebbc2', roughness: 0.22, metalness: 0.82 };
const stone = { preset: 'stone', color: '#30383d', roughness: 0.72 };
const lobbyGlass = { preset: 'glass', color: '#8eb4c5', roughness: 0.1, metalness: 0.08, opacity: 0.72 };
const warm = { preset: 'emissive', color: '#ffd89a', emissive: '#ffc66d', emissiveIntensity: 2.2, roughness: 0.35 };
function dimsForFloor(i) {
  if (i < tier1Top) return [w, d];
  if (i < tier2Top) return [w * 0.78, d * 0.82];
  return [w * 0.57, d * 0.62];
}
function addTier(first, last, tw, td) {
  const y0 = first * floorH;
  const th = (last - first) * floorH;
  api.add(api.box(tw, th, td).translate(0, y0 + th / 2, 0), glass);
}
addTier(0, tier1Top, w, d);
addTier(tier1Top, tier2Top, w * 0.78, d * 0.82);
addTier(tier2Top, floors, w * 0.57, d * 0.62);
const bandH = Math.min(0.18, floorH * 0.075);
for (let i = 1; i < floors; i++) {
  const sz = dimsForFloor(i - 0.1);
  api.add(api.box(sz[0] + 0.08, bandH, sz[1] + 0.08).translate(0, i * floorH, 0), frame);
}
function addMullions(first, last, tw, td, countX, countZ) {
  const y0 = first * floorH;
  const th = (last - first) * floorH;
  const bar = Math.max(0.045, h * 0.0009);
  for (let i = 1; i < countX; i++) {
    const x = -tw / 2 + tw * i / countX;
    api.add(api.box(bar, th, bar).translate(x, y0 + th / 2, td / 2 + bar * 0.35), frame);
    api.add(api.box(bar, th, bar).translate(x, y0 + th / 2, -td / 2 - bar * 0.35), frame);
  }
  for (let i = 1; i < countZ; i++) {
    const z = -td / 2 + td * i / countZ;
    api.add(api.box(bar, th, bar).translate(tw / 2 + bar * 0.35, y0 + th / 2, z), frame);
    api.add(api.box(bar, th, bar).translate(-tw / 2 - bar * 0.35, y0 + th / 2, z), frame);
  }
}
addMullions(0, tier1Top, w, d, 8, 7);
addMullions(tier1Top, tier2Top, w * 0.78, d * 0.82, 6, 6);
addMullions(tier2Top, floors, w * 0.57, d * 0.62, 5, 4);
for (let s = 0; s < 2; s++) {
  const fi = s === 0 ? tier1Top : tier2Top;
  const lower = dimsForFloor(fi - 1);
  const upper = dimsForFloor(fi);
  const y = fi * floorH + 0.12;
  api.add(api.box(lower[0] + 0.55, 0.24, lower[1] + 0.55).translate(0, y, 0), trim);
  api.add(api.box(upper[0] + 0.22, 0.2, upper[1] + 0.22).translate(0, y + 0.16, 0), stone);
}
if (params.lights) {
  const panelH = floorH * 0.42;
  for (let i = 2; i < floors; i += 3) {
    const sz = dimsForFloor(i);
    const y = (i + 0.53) * floorH;
    const pw = sz[0] * 0.23;
    const pd = sz[1] * 0.23;
    const phase = (i % 2) * 0.18;
    api.add(api.box(pw, panelH, 0.035).translate(-sz[0] * 0.2 + phase, y, sz[1] / 2 + 0.055), warm);
    api.add(api.box(pw, panelH, 0.035).translate(sz[0] * 0.2 - phase, y, -sz[1] / 2 - 0.055), warm);
    api.add(api.box(0.035, panelH, pd).translate(sz[0] / 2 + 0.055, y, sz[1] * 0.18 - phase), warm);
    api.add(api.box(0.035, panelH, pd).translate(-sz[0] / 2 - 0.055, y, -sz[1] * 0.18 + phase), warm);
  }
}
api.add(api.box(w * 1.14, podiumH, d * 1.16).translate(0, podiumH / 2, 0), lobbyGlass);
api.add(api.box(w * 1.22, 0.38, d * 1.24).translate(0, 0.19, 0), stone);
api.add(api.box(w * 1.18, 0.24, d * 1.2).translate(0, podiumH + 0.12, 0), trim);
const col = Math.max(0.18, w * 0.025);
for (let side = -1; side <= 1; side += 2) {
  for (let j = -2; j <= 2; j++) {
    api.add(api.box(col, podiumH * 0.82, col).translate(j * w * 0.18, podiumH * 0.45, side * (d * 0.58)), trim);
  }
  api.add(api.box(w * 0.48, 0.24, d * 0.18).translate(0, podiumH * 0.78, side * (d * 0.66)), trim);
}
for (let side = -1; side <= 1; side += 2) {
  api.add(api.box(col, podiumH * 0.82, col).translate(side * (w * 0.57), podiumH * 0.45, -d * 0.18), trim);
  api.add(api.box(col, podiumH * 0.82, col).translate(side * (w * 0.57), podiumH * 0.45, d * 0.18), trim);
}
const topW = w * 0.57;
const topD = d * 0.62;
api.add(api.box(topW * 1.08, 0.32, topD * 1.1).translate(0, h + 0.16, 0), trim);
const crownH = Math.max(1.2, h * 0.03);
api.add(api.box(topW * 0.58, crownH, topD * 0.55).translate(0, h + 0.32 + crownH / 2, 0), frame);
for (let i = -2; i <= 2; i++) {
  api.add(api.box(0.08, crownH * 0.72, topD * 0.58).translate(i * topW * 0.12, h + 0.35 + crownH * 0.36, 0), trim);
}
const mastH = h * 0.11;
const mastBase = h + 0.32 + crownH;
api.add(api.cylinder(h * 0.006, h * 0.011, mastH, 10).translate(0, mastBase + mastH / 2, 0), trim);
api.add(api.sphere(h * 0.014, 1).translate(0, mastBase + mastH, 0), params.lights ? { preset: 'emissive', color: '#ff4b3e', emissive: '#ff2418', emissiveIntensity: 4 } : frame);
api.collider({ kind: 'box', halfExtents: [w * 0.57, podiumH / 2, d * 0.58], offset: [0, podiumH / 2, 0] });
api.collider({ kind: 'box', halfExtents: [w / 2, tier1Top * floorH / 2, d / 2], offset: [0, tier1Top * floorH / 2, 0] });
api.collider({ kind: 'box', halfExtents: [w * 0.39, (tier2Top - tier1Top) * floorH / 2, d * 0.41], offset: [0, (tier1Top + tier2Top) * floorH / 2, 0] });
api.collider({ kind: 'box', halfExtents: [w * 0.285, (floors - tier2Top) * floorH / 2, d * 0.31], offset: [0, (tier2Top + floors) * floorH / 2, 0] });
api.collider({ kind: 'cylinder', radius: h * 0.011, halfHeight: mastH / 2, offset: [0, mastBase + mastH / 2, 0] });
return api.build();
